package in.tucor.api.buyer; import org.springframework.data.jpa.repository.*; import java.util.*; public interface BuyerPickupRepository extends JpaRepository<BuyerPickup,UUID>{List<BuyerPickup> findByBuyerIdOrderByCreatedAtDesc(UUID buyerId);@Query("select p from BuyerPickup p join BuyerOrder o on o.id=p.orderId join MarketListing l on l.id=o.listingId where l.sellerId=:sellerId order by p.createdAt desc") List<BuyerPickup> findForSeller(UUID sellerId);}
